INSERT INTO public.listing_sources (listing_id, source_type, publisher_name, source_url, reference_code, captured_at, notes) VALUES (property_listing_id, 'editorial_import', 'บริษัท บริหารสินทรัพย์สุขุมวิท จำกัด (SAM)', 'https://www.sam.or.th/site/npa/detail.php?id=20424&keyref=6007623', '3A1681', now(), 'Official source captured 2026-09-11. THB 8,838,000, 48 sq.wah, two three-storey shophouse units. Mangrove/title notice read visually in full (2 pages); disclosure retained in Thai/English and terms. Source page background is not treated as legal clearance. 19 URLs contain 18 unique images; identical cover duplicate excluded. Alternate map reference 2T0771 recorded. Navigation/map hrefs agree. All-status duplicate search found no matches.') ;
INSERT INTO public.listing_sources (listing_id, source_type, publisher_name, source_url, reference_code, captured_at, notes) VALUES (property_listing_id, 'editorial_import', 'บริษัท บริหารสินทรัพย์สุขุมวิท จำกัด (SAM)', 'https://npa.sam.or.th/site/attach/npa/20424/ATTACH%203A1681.pdf', '3A1681-NOTICE', now(), 'Two-page specific notice for deed 123145. Mangrove boundary, title provenance and revocation risk, no warranty of lawful issuance, cancellation/refund conditions and buyer acknowledgement. Read full document before offering.') ;
INSERT INTO public.listing_translations (listing_id, language_code, title, description, address_line1, address_line2, road, subdistrict_name, district_name, province_name, seo_title, seo_description, translation_status, translation_source, reviewed_at, search_text) VALUES (property_listing_id, 'en', 'SAM Direct Sale: Phraya Satcha Shophouse, THB 8.838M, Mangrove/Title Notice', 'Two three-storey shophouse units numbered 178/9 on Phraya Satcha Road, Samet, Mueang Chon Buri, Chon Buri. One deed, 123145, covers 48 sq.wah (192 sq.m.). SAM announced price THB 8,838,000; asset 3A1681. The survey describes a roof terrace.
